import torch

class StochasticFunctor:
    def __init__(self, sample_fn):
        self.sample_fn = sample_fn

    @classmethod
    def unit(cls, x):
        """Monadic unit (return)."""
        return cls(lambda: x)

    def bind(self, f):
        """Monadic bind (>>=).

        Sampling stays lazy: every draw from the resulting stochastic value
        first draws a fresh value from `self`, applies `f`, and then draws
        from the resulting stochastic value. This keeps the composition
        dynamic and satisfies the monad laws:
          - left identity:  unit(x) >>= f  ==  f(x)
          - right identity: m >>= unit     ==  m
          - associativity: (m >>= f) >>= g ==  m >>= (lambda x: f(x) >>= g)
        """
        m = self
        return StochasticFunctor(lambda: f(m.sample_fn()).sample_fn())

